    const SAVED_VIEW_SETTINGS_KEY = `${"amex-offer-lite"}:view`;
    let viewSettingsReadFailed = false;
    function restoreViewSettings() {
        try {
            const saved = GM_getValue(SAVED_VIEW_SETTINGS_KEY, null);
            if (saved === null) return;
            if (saved.schemaVersion !== 1 || typeof saved.filter !== 'string' || typeof saved.minimized !== 'boolean') {
                throw new Error('Unsupported saved view');
            }
            state.filter = saved.filter;
            state.minimized = saved.minimized;
        } catch {
            viewSettingsReadFailed = true;
            log('Could not restore display settings. Stored data was preserved.');
        }
    }
    function persistViewSettings() {
        if (viewSettingsReadFailed) return;
        try {
            GM_setValue(SAVED_VIEW_SETTINGS_KEY, { schemaVersion: 1, filter: state.filter, minimized: state.minimized });
        } catch { log('Could not save search and panel settings. Check Tampermonkey storage.'); }
    }

    // Source: core/saved-cards.js
    const SAVED_CARDS_SCHEMA_VERSION = 2;

    function validateSavedCards(snapshot) {
        if (!snapshot || ![1, SAVED_CARDS_SCHEMA_VERSION].includes(snapshot.schemaVersion) || typeof snapshot.detected !== 'boolean' ||
            !Array.isArray(snapshot.accounts) || !Array.isArray(snapshot.whitelist)) {
            throw new Error('Saved card settings have an unrecognized format.');
        }
        const validString = (value) => typeof value === 'string' && value.length > 0;
        // v1 stored no offer priority. Detection order becomes the starting order, so
        // upgrading never reshuffles cards and never sends a request.
        const priorityOrder = snapshot.schemaVersion === 1 ? snapshot.accounts.map((account) => account.token) : snapshot.priorityOrder;
        if (snapshot.accounts.some((account) => !account || !validString(account.token) || !validString(account.cardName)) ||
            snapshot.whitelist.some((token) => !validString(token)) ||
            !Array.isArray(priorityOrder) || priorityOrder.some((token) => !validString(token)) ||
            new Set(priorityOrder).size !== priorityOrder.length ||
            new Set(snapshot.accounts.map((account) => account.token)).size !== snapshot.accounts.length ||
            (snapshot.detected && !snapshot.accounts.length) || (!snapshot.detected && snapshot.accounts.length)) {
            throw new Error('Saved card settings are incomplete or invalid.');
        }
        return {
            accounts: snapshot.accounts.map(({ token, cardName }) => ({ token, cardName })),
            whitelist: new Set(snapshot.whitelist),
            cardPriority: priorityOrder,
            detected: snapshot.detected
        };
    }

    function reportCardStorageError(message) {
        state.savedCardsError = message;
        log(message);
    }

    function persistCardSettings() {
        try {
            // Store one snapshot so the catalog, the explicit approvals and the offer
            // priority stay together and can never restore out of step with each other.
            GM_setValue(SETTINGS.savedCardsKey, {
                schemaVersion: SAVED_CARDS_SCHEMA_VERSION,
                detected: state.detected,
                accounts: state.accounts.map(({ token, cardName }) => ({ token, cardName })),
                whitelist: [...state.whitelist],
                priorityOrder: normalizeCardPriority()
            });
            state.savedCardsReady = true;
            state.savedCardsError = '';
            return true;
        } catch {
            reportCardStorageError('Could not save cards and whitelist. Changes apply to this page only; check Tampermonkey storage.');
            return false;
        }
    }

    function migrateLegacyWhitelist() {
        let legacyValue;
        try {
            legacyValue = localStorage.getItem(SETTINGS.whitelistKey);
        } catch {
            log('Previous website storage is unavailable. New card settings will be saved in Tampermonkey.');
            return;
        }
        if (legacyValue === null) return;
        const legacyWhitelist = JSON.parse(legacyValue);
        if (!Array.isArray(legacyWhitelist)) throw new Error('Legacy whitelist has an unrecognized format.');
        state.whitelist = new Set(legacyWhitelist.filter((token) => typeof token === 'string' && token));
        // v4.0/v4.1 saved no catalog. Recover it from already-loaded page data once,
        // if available; upgrading must never trigger an account or offer request.
        try {
            const accounts = accountsFromPage(readPageState());
            if (accounts.length) {
                state.accounts = accounts;
                state.detected = true;
            }
        } catch {
            log('Saved whitelist recovered. Detect the card list manually to display it.');
        }
        if (persistCardSettings()) log('Previous whitelist migrated to Tampermonkey storage.');
    }

    function restoreSavedCards() {
        try {
            const snapshot = GM_getValue(SETTINGS.savedCardsKey, null);
            if (snapshot === null) migrateLegacyWhitelist();
            else {
                Object.assign(state, validateSavedCards(snapshot));
                state.savedCardsReady = true;
            }
            if (state.detected) {
                normalizeCardPriority();
                state.status = `Restored ${state.accounts.length} cards, ${selectedAccounts().length} whitelist selections and your offer priority. Ready to scan manually.`;
            } else if (state.whitelist.size) {
                state.status = 'Your whitelist is saved. Detect the card list once to display your existing selections.';
            }
        } catch {
            reportCardStorageError('Could not restore saved cards and whitelist. Saved data was not overwritten; check Tampermonkey storage.');
        }
    }

    // Source: core/offer-snapshots.js
    const SAVED_OFFER_FIELDS = ['id', 'name', 'description', 'expiry', 'status', 'type', 'groupKey'];
    const SAVED_OFFER_STATUSES = new Set(['ELIGIBLE', 'ENROLLED', 'UNKNOWN', 'FAILED', 'UNCONFIRMED']);

    function enrollmentStorageKey(accountToken, groupKey) {
        return JSON.stringify([accountToken, groupKey]);
    }

    function offerSnapshotValue(offer) {
        if (!offer || SAVED_OFFER_FIELDS.some((field) => typeof offer[field] !== 'string') ||
            !offer.id || !offer.groupKey || typeof offer.enrollable !== 'boolean' || !SAVED_OFFER_STATUSES.has(offer.status)) {
            throw new Error('Saved offer data has an unrecognized format.');
        }
        return { ...Object.fromEntries(SAVED_OFFER_FIELDS.map((field) => [field, offer[field]])), enrollable: offer.enrollable };
    }

    function validateOfferSnapshot(snapshot) {
        if (!snapshot || snapshot.schemaVersion !== 1 || !Array.isArray(snapshot.cards)) {
            throw new Error('Saved offers have an unrecognized format.');
        }
        const accounts = new Set();
        return snapshot.cards.map((card) => {
            if (!card || typeof card.accountToken !== 'string' || !card.accountToken || accounts.has(card.accountToken) ||
                !Array.isArray(card.offers) || typeof card.complete !== 'boolean' || !Number.isFinite(card.scannedAt) || card.scannedAt < 0) {
                throw new Error('Saved card offers are incomplete or invalid.');
            }
            accounts.add(card.accountToken);
            return { accountToken: card.accountToken, complete: card.complete, scannedAt: card.scannedAt,
                offers: card.offers.map(offerSnapshotValue) };
        });
    }

    // Source: core/saved-offers.js
    function persistOfferResults() {
        try {
            const cards = [...state.offersByAccount].map(([accountToken, offers]) => ({
                accountToken,
                complete: state.scanReports.get(accountToken)?.startsWith('Complete') || false,
                scannedAt: state.offerScanTimes.get(accountToken) || 0,
                offers: offers.map((offer) => {
                    const snapshot = offerSnapshotValue(offer);
                    // A reload cannot tell whether an in-flight enrollment succeeded.
                    // Persist uncertainty before sending, never a retryable stale state.
                    if (state.pendingEnrollments.has(enrollmentStorageKey(accountToken, offer.groupKey))) snapshot.status = 'UNCONFIRMED';
                    return snapshot;
                })
            }));
            GM_setValue(SETTINGS.savedOffersKey, { schemaVersion: 1, cards });
            state.savedOffersError = '';
            return true;
        } catch {
            state.savedOffersError = 'Could not save offers. These changes apply to this page only; check Tampermonkey storage.';
            log(state.savedOffersError);
            return false;
        }
    }

    function restoreSavedOffers() {
        try {
            const snapshot = GM_getValue(SETTINGS.savedOffersKey, null);
            if (snapshot === null) return;
            const cards = validateOfferSnapshot(snapshot);
            for (const card of cards) {
                state.offersByAccount.set(card.accountToken, card.offers);
                state.scanReports.set(card.accountToken, card.complete ? 'Complete' : 'Incomplete');
                state.offerScanTimes.set(card.accountToken, card.scannedAt);
            }
            if (cards.length) {
                state.status = 'Saved offers restored. Review them now or refresh whitelist offers manually.';
                log('Saved offer results restored without sending requests.');
            }
        } catch {
            state.savedOffersError = 'Could not restore saved offers. Saved data was not overwritten.';
            log(state.savedOffersError);
        }
    }

    // Source: core/page-state.js
    // The captured Amex page uses uncached Transit immutable maps/lists and JSON maps.
    // Parse data only: never evaluate the page's initial-state script.
    function decodePageState(value) {
        if (typeof value === 'string') {
            if (/^\^[0-9A-Za-z]/.test(value)) throw new Error('Unsupported compressed page state.');
            return value.startsWith('~~') ? value.slice(1) : value;
        }
        if (!Array.isArray(value)) return value;
        if (value[0] === '^ ') {
            if (value.length % 2 !== 1) throw new Error('Invalid page-state map.');
            return Object.fromEntries(Array.from({ length: (value.length - 1) / 2 }, (_, index) => [
                value[index * 2 + 1], decodePageState(value[index * 2 + 2])
            ]));
        }
        if (value[0] === '~#iM') {
            const entries = value[1];
            if (!Array.isArray(entries) || entries.length % 2 !== 0) throw new Error('Invalid immutable map.');
            return Object.fromEntries(Array.from({ length: entries.length / 2 }, (_, index) => [
                entries[index * 2], decodePageState(entries[index * 2 + 1])
            ]));
        }
        if (value[0] === '~#iL' || value[0] === '~#iS') return value[1].map(decodePageState);
        return value.map(decodePageState);
    }

    function readPageState() {
        const pageWindow = typeof unsafeWindow === 'undefined' ? window : unsafeWindow;
        let initialState = pageWindow.__INITIAL_STATE__;
        if (!initialState) {
            const script = document.getElementById('initial-state')?.textContent || '';
            const assignment = script.match(/window\.__INITIAL_STATE__\s*=\s*("(?:[^"\\]|\\.)*")/);
            if (assignment) initialState = JSON.parse(assignment[1]);
        }
        if (typeof initialState === 'string') initialState = JSON.parse(initialState);
        return decodePageState(initialState);
    }

