    // Source: api/requests.js
    class RequestStopped extends Error {}
    class RateLimited extends Error {}

    function requireActiveRequest() {
        if (state.cancelRequested) throw new RequestStopped('Stopped. No further requests will be sent.');
    }

    async function waitForRequestSlot() {
        requireActiveRequest();
        if (Date.now() < state.cooldownUntil) throw new RateLimited('Cooling down after HTTP 429. Start again manually when the timer ends.');
        while (Date.now() < state.nextRequestAt) {
            requireActiveRequest();
            const remainingMs = state.nextRequestAt - Date.now();
            setStatus(`Waiting ${Math.ceil(remainingMs / 1000)}s before the next request. Stop is available.`);
            await new Promise((resolve) => setTimeout(resolve, Math.min(250, remainingMs)));
        }
        requireActiveRequest();
    }

    function retryAfterMilliseconds(headerValue) {
        if (!headerValue) return SETTINGS.rateLimitCooldownMs;
        const seconds = Number(headerValue);
        const delay = Number.isFinite(seconds) ? seconds * 1000 : Date.parse(headerValue) - Date.now();
        return Number.isFinite(delay) ? Math.max(SETTINGS.rateLimitCooldownMs, delay) : SETTINGS.rateLimitCooldownMs;
    }

    async function withRequestSlot(operation) {
        if (state.requestInFlight) throw new Error('Another request is still active.');
        state.requestInFlight = true;
        try {
            await waitForRequestSlot();
            return await operation();
        } finally {
            // A slot holds one scan request or one complete concurrent offer batch.
            // The next slot waits from the last response, including failures.
            state.nextRequestAt = Math.max(state.nextRequestAt, Date.now() + SETTINGS.requestGapMs);
            state.requestInFlight = false;
        }
    }

    function requestJson(url, options = {}) {
        return withRequestSlot(() => sendJsonRequest(url, options));
    }

    function requestHub(endpoint, accountToken, payload) {
        assertWhitelisted(accountToken);
        return requestJson(`${SETTINGS.functionsBase}/${endpoint}`, {
            accountToken, body: { accountNumberProxy: accountToken, locale: 'en-US', ...payload }
        });
    }

    // Source: api/transport.js
    // Call only while holding a request slot. Same-offer enrollments share one slot;
    // scan requests and different offers each acquire their own slot.
    async function sendJsonRequest(url, { body, accountToken, source = 'WEB' } = {}) {
        requireActiveRequest();
        if (accountToken) assertWhitelisted(accountToken);
        let timeoutId;
        try {
            const controller = new AbortController();
            timeoutId = setTimeout(() => controller.abort(), SETTINGS.requestTimeoutMs);
            const headers = { Accept: 'application/json', 'ce-source': source, 'one-data-correlation-id': crypto.randomUUID() };
            if (body) headers['Content-Type'] = 'application/json';
            const response = await fetch(url, {
                method: body ? 'POST' : 'GET', credentials: 'include', headers,
                ...(body ? { body: JSON.stringify(body) } : {}), signal: controller.signal
            });
            if (response.status === 429) {
                state.cooldownUntil = Math.max(state.cooldownUntil, Date.now() + retryAfterMilliseconds(response.headers.get('Retry-After')));
                persistCooldown();
                throw new RateLimited('HTTP 429: this run stopped. No automatic retry will be made.');
            }
            if (!response.ok) throw new Error(`HTTP ${response.status}. No automatic retry was made.`);
            try {
                return await response.json();
            } catch {
                throw new Error('The response was not valid JSON; the result is unconfirmed.');
            }
        } catch (error) {
            if (error.name === 'AbortError') throw new Error('Request timed out; the result is unconfirmed. No automatic retry was made.');
            throw error;
        } finally {
            clearTimeout(timeoutId);
        }
    }

    // Source: api/accounts.js
    function normalizeAccounts(accountList) {
        const accounts = new Map();
        function visit(account) {
            if (!account || typeof account !== 'object') return;
            if (typeof account.account_token === 'string' && account.account_token) {
                const cardType = account.product?.description || 'Amex card';
                const cardholder = account.profile?.first_name || '';
                const displayNumber = account.account?.display_account_number || '';
                accounts.set(account.account_token, {
                    token: account.account_token,
                    cardName: [cardType, cardholder, displayNumber ? `(${displayNumber})` : ''].filter(Boolean).join(' · ')
                });
            }
            if (Array.isArray(account.supplementary_accounts)) account.supplementary_accounts.forEach(visit);
        }
        accountList.forEach(visit);
        return [...accounts.values()];
    }

    function accountsFromPage(pageState) {
        for (const moduleName of ['axp-consumer-context-switcher', 'axp-loyalty-root']) {
            const products = pageState?.modules?.[moduleName]?.products?.details?.types?.CARD_PRODUCT?.productsList;
            if (products && typeof products === 'object') {
                const accounts = normalizeAccounts(Object.values(products));
                if (accounts.length) return accounts;
            }
        }
        return Array.isArray(pageState?.accounts) ? normalizeAccounts(pageState.accounts) : [];
    }

    async function detectAccountSnapshot({ forceRefresh = false } = {}) {
        if (!forceRefresh) {
            try {
                const accounts = accountsFromPage(readPageState());
                if (accounts.length) return { accounts, source: 'existing page data; no network request' };
            } catch {
                log('Page card data is unavailable. Trying one account-list request.');
            }
        }
        // One fallback or explicit refresh request; never iterate through cards here.
        const member = await requestJson('https://global.americanexpress.com/api/servicing/v1/member');
        if (!Array.isArray(member?.accounts)) throw new Error('Account-list format was not recognized. Open the Amex Offers page and reload.');
        const accounts = normalizeAccounts(member.accounts);
        if (!accounts.length) throw new Error('No cards were found in this session.');
        return { accounts, source: 'one account-list request' };
    }

    // Source: api/offers.js
    class OfferSchemaError extends Error {}

    function offersInSection(response, sectionName) {
        if (response?.status?.purpose && response.status.purpose !== 'SUCCESS') {
            throw new Error('Offers Hub reported an unsuccessful response.');
        }
        const section = response?.[sectionName];
        const pages = section?.offersList;
        if (!pages || typeof pages !== 'object' || Array.isArray(pages)) {
            throw new OfferSchemaError(`Offers Hub ${sectionName}.offersList was not recognized; this view is incomplete.`);
        }
        if (section.hasMore === true || section.nextPage || response.hasMore === true || response.nextPage) {
            throw new OfferSchemaError('Offers Hub indicated additional server pages; this view is incomplete.');
        }
        const offers = Object.values(pages).flatMap((page) => {
            if (!Array.isArray(page)) throw new OfferSchemaError('An Offers Hub page was not a list.');
            return page;
        });
        if (offers.some((offer) => !offer || typeof offer.offerId !== 'string')) {
            throw new OfferSchemaError('An Offer did not contain a valid identifier.');
        }
        return offers;
    }

    function normalizeHubOffer(offer) {
        const enrollmentStatus = offer.enrollmentDetails?.status;
        const status = enrollmentStatus === 'NOT_ENROLLED' ? 'ELIGIBLE'
            : enrollmentStatus === 'ENROLLED' ? 'ENROLLED' : 'UNKNOWN';
        const name = offer.title || 'Untitled offer';
        const description = offer.shortDescription || '';
        const expiry = offer.expiration?.text || '';
        return {
            id: offer.offerId, name, description, expiry, status,
            type: offer.offerType || 'UNKNOWN',
            enrollable: offer.offerType === 'MERCHANT' && offer.ctaDetails?.ctaType === 'MODAL',
            // Hub IDs may be card-specific. Group only offers with the same visible terms.
            groupKey: JSON.stringify([offer.offerType, name, description, expiry, offer.longDescription || '', offer.terms?.details || '']
                .map((value) => String(value || '').replace(/\s+/g, ' ').trim()))
        };
    }

    async function getAllOffersForAccount(accountToken, onProgress = () => {}) {
        const collected = new Map();
        const viewErrors = [];
        for (const [requestType, sectionName] of [
            ['OFFERSHUB_LANDING', 'recommendedOffers'],
            // The full added view has a different key from the landing/enrollment preview.
            ['ADDEDTOCARD_LANDING', 'addedToCardViewAll']
        ]) {
            requireActiveRequest();
            const response = await requestHub('ReadOffersHubPresentation.web.v1', accountToken, {
                offerPage: 'page1', requestType
            });
            if (response?.accountNumberProxy && response.accountNumberProxy !== accountToken) {
                throw new Error('Offers Hub returned a different card; this scan was stopped.');
            }
            try {
                for (const rawOffer of offersInSection(response, sectionName)) {
                    const offer = normalizeHubOffer(rawOffer);
                    // Prefer the enrolled view if the same offer appears in both lists.
                    if (collected.get(offer.id)?.status !== 'ENROLLED') collected.set(offer.id, offer);
                }
            } catch (error) {
                if (!(error instanceof OfferSchemaError)) throw error;
                viewErrors.push(error.message);
                // Preserve valid results and continue to the other view/card at the same slow pace.
            }
            onProgress([...collected.values()]);
        }
        return { offers: [...collected.values()], viewErrors };
    }

    // Source: api/enrollment-contract.js
    // The existing v3.4 userscript and the 2026-09-10 HAR both use this contract.
    // Keep full-list reads on Offers Hub; changing the list API need not change writes.
    const CARD_ENROLLMENT_ENDPOINT = 'CreateCardAccountOfferEnrollment.v1';

    function enrollmentUserOffset(date) {
        const offsetMinutes = -date.getTimezoneOffset();
        const hours = Math.floor(Math.abs(offsetMinutes) / 60);
        const minutes = Math.abs(offsetMinutes) % 60;
        return `${offsetMinutes >= 0 ? '+' : '-'}${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}`;
    }

    function cardEnrollmentBody(accountToken, offerIdentifier, requestDate = new Date()) {
        return {
            accountNumberProxy: accountToken,
            identifier: offerIdentifier,
            locale: 'en-US',
            requestDateTimeWithOffset: requestDate.toISOString(),
            userOffset: enrollmentUserOffset(requestDate)
        };
    }

    function cardEnrollmentStatus(response, accountToken, offerIdentifier) {
        if (!response || typeof response !== 'object' || Array.isArray(response)) return 'UNCONFIRMED';
        if (response.accountNumberProxy && response.accountNumberProxy !== accountToken) return 'UNCONFIRMED';
        if (response.identifier && response.identifier !== offerIdentifier) return 'UNCONFIRMED';
        if (response.status?.purpose === 'FAILURE' || response.status?.purpose === 'ERROR' || response.isEnrolled === false) return 'FAILED';
        // The original `isEnrolled || true` falsely reported false/missing values as
        // success. Only the literal boolean observed in the successful HAR is valid.
        return response.isEnrolled === true ? 'ENROLLED' : 'UNCONFIRMED';
    }

